corrected_code:
const serverless = require('@codegenie/serverless-express');
const express = require('express');
const { db } = require('../db');

const app = express();

app.post('/api/orders/:orderId/cancel', async (req, res) => {
  const { orderId } = req.params;
  const customerId = req.apiGateway?.event?.requestContext?.authorizer?.customerId;

  if (!customerId) {
    return res.status(401).json({ error: 'Unauthorized: missing authorizer context' });
  }

  const result = await db.query(
    "UPDATE customer_orders SET status = 'CANCELLED' WHERE id = $1 AND customer_id = $2 RETURNING *",
    [orderId, customerId]
  );
  if (!result.rows.length) {
    return res.status(403).json({ error: 'Order not found or does not belong to you' });
  }

  res.json({ cancelled: true, order: result.rows[0] });
});

exports.handler = serverless({ app });
